import heapq, math

def dijkstra(g, s, t):
    dist, prev, pq = {s: 0}, {}, [(0, s)]
    while pq:
        d, u = heapq.heappop(pq)
        if u == t: break
        if d > dist[u]: continue
        for v, w in g[u]:
            if d + w < dist.get(v, math.inf):
                dist[v], prev[v] = d + w, u
                heapq.heappush(pq, (d + w, v))
    path = [t]
    while path[-1] != s: path.append(prev[path[-1]])
    return dist[t], path[::-1]

def graph(kmh):  # 링크 길이(m) ÷ 속도 → 초
    links = {('A','B'): 2000, ('B','D'): 3000, ('A','C'): 2500, ('C','D'): 3500}
    g = {n: [] for n in 'ABCD'}
    for (u, v), L in links.items():
        g[u].append((v, round(L / (kmh[u+v] / 3.6))))
    return g

free = dict(AB=60, BD=60, AC=60, CD=60)
jam = dict(free, BD=15)
for name, k in [('평소', free), ('B→D 정체', jam)]:
    d, p = dijkstra(graph(k), 'A', 'D')
    print(name, '→'.join(p), f'{d/60:.1f}분')
# 평소 A→B→D 5.0분
# B→D 정체 A→C→D 6.0분

